import{_ as a,o as i,c as l,aw as o}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"Webpack 5. Module Federation (MF)","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/common2/webpack/module-federation/info.md","filePath":"wiki/dev-commit/common2/webpack/module-federation/info.md"}'),t={name:"wiki/dev-commit/common2/webpack/module-federation/info.md"};function r(n,e,d,s,c,u){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="webpack-5-module-federation-mf" tabindex="-1">Webpack 5. Module Federation (MF) <a class="header-anchor" href="#webpack-5-module-federation-mf" aria-label="Permalink to &quot;Webpack 5. Module Federation (MF)&quot;">​</a></h1><ul><li>Есть 2 приложения - неважно на чем они написаны (в примере Next.js и React.js)</li><li>Их можно встроить в приложение-контейнер Host Container</li><li>Похоже на iFrame, но при использованиие iFrame отдается приложение полностью</li><li>Для Module Federation отдается JS-код и уже он запускается в Host Container. Можно отдать не весь код приложения, а только определенные части и всё что можно экспортировать: отдельный компонент, константу и т.д.</li><li>Экспортируется JavaScript-код, поэтому исходное приложение может быть написано на любом фреймворке</li><li>Module Federation можно шарить зависимости: установить 1 раз и остальные приложения могут использовать уже установленные зависимости</li></ul><hr><h2 id="терминология" tabindex="-1">Терминология <a class="header-anchor" href="#терминология" aria-label="Permalink to &quot;Терминология&quot;">​</a></h2><ul><li><strong>Host (consumers)</strong> - бандл, который первый инициализировался во время загрузки страницы (корень)</li><li><strong>Remote (consumable)</strong> - другой бандл, чьи некоторые части может импортировать host (лист)</li><li><strong>Omnidirectional host</strong> - бандл, который одновременно может быть и host и remote (внутренний узел)</li><li><strong>Exposed modules</strong> - модули, которые будут доступны другим приложениям для импорта</li><li><strong>Shared modules</strong> - модули, которые могут быть общими для всего приложения (н-р: React)</li></ul><h2 id="теория" tabindex="-1">Теория <a class="header-anchor" href="#теория" aria-label="Permalink to &quot;Теория&quot;">​</a></h2><h3 id="общее" tabindex="-1">Общее <a class="header-anchor" href="#общее" aria-label="Permalink to &quot;Общее&quot;">​</a></h3><ul><li>Webpack 5 (октябрь 2020)</li><li>Разработал Zack Jackson совместно с другими разработчиками</li></ul><h3 id="функционал" tabindex="-1">Функционал <a class="header-anchor" href="#функционал" aria-label="Permalink to &quot;Функционал&quot;">​</a></h3><ul><li>Позволяет одному Webpack-приложению ДИНАМИЧЕСКИ подгружать код из другого Webpack-приложения, расположенного на другом хосте</li><li>MF - core webpack-plugin, который позволяет импортировать chunk&#39;и из стороннего Webpack Bundle В РАНТАЙМЕ</li><li>Все что может сбандлить Webpack (css, images, fonts, ...) с MF может быть зашарено между микрофронтендами</li><li>MF может ШАРИТЬ между собой ОБЩИЕ ЗАВИСИМОСТИ, если совпадает semver. К примеру, если React уже загружен, то он не будет поторно грузиться со стороннего Webpack приложения</li><li>MF могут быть разернуты на разных доменах и ДЕПЛОИТЬСЯ НЕЗАВИСИМО</li><li>Сборка происходит на лету при запуске приложения в браузере</li></ul><h3 id="цели" tabindex="-1">Цели <a class="header-anchor" href="#цели" aria-label="Permalink to &quot;Цели&quot;">​</a></h3><ul><li>Нет перезагрузки страниц при переходе между микрофронтендами</li><li>Не грузить vendor code, который уже предоствлен другой Webpack-сборкой (н-р: React)</li><li>Каждый микрофронтенд может быть standalone (без внешних зависимостей)</li><li>Не нужно пересобирать основное приложение, если применяется shared-модуль (н-р: Навигация)</li><li>Оркестрация должана происходить на стороне пользователя, позвляя загружать чанки без &quot;умного сервера&quot; (чтобы спокойно раздаваться с CDN и не только)</li></ul><h3 id="резюме" tabindex="-1">Резюме <a class="header-anchor" href="#резюме" aria-label="Permalink to &quot;Резюме&quot;">​</a></h3><ul><li>У каждого микрофронтенда может быть свой репозиторий</li><li>Независимые билды и деплой</li><li>Микрофронтенд может быть запущен как standalone SPA</li><li>В браузере все работает как монолит</li></ul>',14)])])}const b=a(t,[["render",r]]);export{h as __pageData,b as default};
